<script setup lang="ts">
import {leadTimeChart} from '~/utils/leadTimeChart'
const props=defineProps<{data:any;compare:boolean}>()
const tableOnly=ref(false)
const chart=computed(()=>leadTimeChart(props.data.items||[],props.data.lead_time?.total))
const colors:Record<string,string>={pick:'#BFB9FE',pack:'#9B8AFB',handover:'#7855FE'}
const {t}=useI18n()
const stages=['pick','pack','handover','total']
const format=(value:number|null|undefined)=>value==null?'—':(value/24).toLocaleString(undefined,{maximumFractionDigits:2})
</script>
<template><WCard class="lead-time" :title="t('document-report.lead-title')" :subtitle="t('document-report.lead-unit')">
  <template #actions><WButton variant="text" size="sm" @click="tableOnly=!tableOnly">{{t('document-report.'+(tableOnly?'view-chart':'view-table'))}}</WButton></template>
  <p>{{t('document-report.lead-help')}}</p>
  <div class="lead-layout"><div class="stage-summary"><div class="table-scroll"><table><thead><tr><th>{{t('document-report.stage')}}</th><th>{{t('document-report.median')}}</th><th>P90</th><th v-if="compare">{{t('document-report.previous-median')}}</th><th>{{t('document-report.samples')}}</th></tr></thead><tbody>
    <tr v-for="(key,index) in stages" :key="key" :class="{total:key==='total'}"><td><span class="dot" :style="{background:['#BFB9FE','#9B8AFB','#7855FE','#151923'][index]}"/>{{t('document-report.stage-'+key)}}</td><td class="median">{{format(data.lead_time?.[key]?.median_hours)}}</td><td>{{format(data.lead_time?.[key]?.p90_hours)}}</td><td v-if="compare" class="previous">{{format(data.previous_lead_time?.[key]?.median_hours)}}</td><td>{{data.lead_time?.[key]?.count??0}}</td></tr>
  </tbody></table></div>
    <div v-if="data.slowest" class="slowest"><NuxtLink :to="'/dn/detail/'+data.slowest.id">DN-{{data.slowest.id}}</NuxtLink> · {{t('document-report.slowest')}} {{format(data.slowest.total_hours)}} {{t('inventory-analysis.days')}}<template v-if="data.slowest.stage"> · {{t('document-report.stage-'+data.slowest.stage)}} {{format(data.slowest.stage_hours)}} {{t('inventory-analysis.days')}}</template></div>
  </div>
  <div v-if="!tableOnly" class="chart-scroll"><p class="page-note">{{t('document-report.lead-page')}}</p><WEmptyState v-if="!chart.rows.length" compact :title="t('w.table.empty')"/><div v-else class="lead-chart">
    <div class="reference-labels"><span v-for="ref in chart.references" :key="ref.key" :style="{left:ref.percent+'%'}">{{ref.key==='median_hours'?t('document-report.median'):'P90'}}</span></div>
    <NuxtLink v-for="row in chart.rows" :key="row.id" class="lead-row" :to="'/dn/detail/'+row.id"><span class="document"><strong>DN-{{row.id}}</strong><small>{{row.actual_date||'—'}}</small></span><span class="track"><i v-for="ref in chart.references" :key="ref.key" class="reference" :style="{left:ref.percent+'%'}"/><span v-if="row.complete" class="segments" :style="{width:row.total/chart.maximum*100+'%'}"><i v-for="segment in row.segments" :key="segment.key" :style="{flex:segment.hours,background:colors[segment.key]}" :title="t('document-report.stage-'+segment.key)+': '+format(segment.hours)"/></span><span v-else class="missing">{{t('document-report.missing-stages')}}</span></span><span class="row-total">{{format(row.total)}}<small v-if="row.on_time===false">{{t('document-report.late-shipment')}}</small></span></NuxtLink>
    <div class="chart-axis"><span v-for="tick in chart.ticks" :key="tick.percent" :style="{left:tick.percent+'%'}">{{format(tick.hours)}}</span></div>
  </div></div></div>
</WCard></template>
